customers = [
    {"id": "c1", "name": " Alice ", "tier": "gold"},
    {"id": "c2", "name": "Bob",    "tier": "silver"},
]

# Dict comprehension: id -> full record for O(1) enrichment/joins
by_id = {c["id"]: c for c in customers}

# Dict comprehension: reshape/clean a raw config (strip + lowercase keys)
raw = {" SOURCE ": " crm ", "Batch_Size": " 500 "}
clean = {k.strip().lower(): v.strip() for k, v in raw.items()}

# Filter while reshaping: keep only gold-tier names, id -> name
gold_names = {c["id"]: c["name"].strip() for c in customers if c["tier"] == "gold"}

print(by_id["c1"]["tier"])
print(clean)
print(gold_names)
